2	
3	import org.junit.jupiter.api.Tag;
4	import org.junit.jupiter.api.Test;
5	import static org.junit.jupiter.api.Assertions.assertNotEquals;
6	
7	/** code-collision: on a customerCode collision, append '-&lt;n&gt;' (smallest n &gt;= 2) to keep it
8	 * unique. A genuine hash collision cannot be forced black-box (it needs an identical
9	 * normalizedTelephone + lastName, which telephone-uniqueness already blocks), so assert the rule's
10	 * guarantee instead: distinct owners always get distinct customerCodes. */
11	@Tag("cp41")
12	class Cp41Tests extends AcceptanceBase {
13	
14		@Test
15		void coreCustomerCodesStayUnique() throws Exception {
16			String c1 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
17			String c2 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
18			assertNotEquals(c1, c2);
19		}
20	}
