63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
74	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
75	     * and a dotted domain (e.g. {@code not-an-email}).
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
78	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
79	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
80	
81	    /**
82	     * Disposable email domains that are not allowed for an owner. An email whose domain (the part
83	     * after the '@', compared case-insensitively) is listed here is rejected with 400 Bad Request.
84	     */
85	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
86	        "mailinator.com",
87	        "tempmail.com",
88	        "guerrillamail.com");
89	
90	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
91	    private static final String DEFAULT_COUNTRY_CODE = "61";
92	
93	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
94	    private static final int MAX_OWNERS_PER_CITY = 50;
95	
96	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
97	    private static final int MAX_OWNERS_PER_DAY = 100;
98	
99	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
100	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
101	
102	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
103	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
104	
105	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
106	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
107	
108	    /**
109	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
110	     * is listed here must carry exactly the required number of national digits, otherwise it is
111	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
112	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
113	     */
114	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
115	        "61", 9,
116	        "1", 10);
117	
118	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
119	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
120	        "ST", "STREET",
121	        "RD", "ROAD",
122	        "AVE", "AVENUE");
123	
124	    /** A well-formed postcode: exactly four digits. */
125	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
126	
127	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
128	    private static final Map<String, String> CITY_REGION = Map.of(
129	        "Sydney", "NSW",
130	        "Melbourne", "VIC",
131	        "Brisbane", "QLD");
132	
133	    /** Region to its inclusive 4-digit postcode range {low, high}. */
134	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
135	        "NSW", new int[] {2000, 2099},
136	        "VIC", new int[] {3000, 3099},
137	        "QLD", new int[] {4000, 4099});
138	
139	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
140	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
141	
142	    private final ClinicService clinicService;
143	
144	    private final OwnerMapper ownerMapper;
145	
146	    private final PetMapper petMapper;
147	
148	    private final VisitMapper visitMapper;
149	
150	    public OwnerRestControllerV1(ClinicService clinicService,
151	                                 OwnerMapper ownerMapper,
152	                                 PetMapper petMapper,
153	                                 VisitMapper visitMapper) {
154	        this.clinicService = clinicService;
155	        this.ownerMapper = ownerMapper;
156	        this.petMapper = petMapper;
157	        this.visitMapper = visitMapper;
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
163	        Collection<Owner> owners;
164	        if (lastName != null) {
165	            owners = this.clinicService.findOwnerByLastName(lastName);
166	        } else {
167	            owners = this.clinicService.findAllOwners();
168	        }
169	        if (owners.isEmpty()) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        owners.forEach(this::populateHouseholdSize);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
179	        Owner owner = this.clinicService.findOwnerById(ownerId);
180	        if (owner == null) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        populateHouseholdSize(owner);
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
190	        List<String> missingFields = new ArrayList<>();
191	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
192	            missingFields.add("firstName");
193	        }
194	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
195	            missingFields.add("lastName");
196	        }
197	        // Normalize the address up front; the required-field check rejects it when it is blank
198	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
199	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
200	        if (!StringUtils.hasText(normalizedAddress)) {
201	            missingFields.add("address");
202	        }
203	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
204	            missingFields.add("city");
205	        }
206	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
207	            missingFields.add("telephone");
208	        }
209	        if (!missingFields.isEmpty()) {
210	            throw new InvalidRequestException(missingFields);
211	        }
212	        HttpHeaders headers = new HttpHeaders();
213	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
214	        // Store (and later return) the normalized address computed above.
215	        owner.setAddress(normalizedAddress);
216	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
217	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
218	        owner.setTelephone(normalizedTelephone);
219	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
220	        owner.setEmail(normalizeEmail(owner.getEmail()));
221	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
222	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
223	        validatePostcode(owner.getCity(), owner.getPostcode());
224	        // Reject a supplied registration date that lies in the future (later than the server's current
225	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
226	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
227	            throw new InvalidRequestException(List.of("registrationDate"));
228	        }
229	        // Default the (optional) registration date to the server's current date when none was supplied.
230	        if (owner.getRegistrationDate() == null) {
231	            owner.setRegistrationDate(LocalDate.now());
232	        }
233	        // The effective registration date must fall on a business day: when it lands on a Saturday or
234	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
235	        // derived from the registration date below (daily create-limit, membership number) uses this
236	        // adjusted date.
237	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
238	        // Reject the request once the maximum number of owners for the owner's registration day has
239	        // been reached (100 or more owners already created on that date).
240	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
241	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
242	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
243	        }
244	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
245	        // owner's registration day at the moment this owner was created; otherwise clear it.
246	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
247	        // Reject the request when the owner's city has already reached its owner capacity.
248	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
249	            throw new CityCapacityException(owner.getCity());
250	        }
251	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
252	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
253	        // so any two owners with the same last name and postcode automatically resolve to the same
254	        // household without an explicit opt-in. It is assigned up front so it feeds duplicate
255	        // detection (the identity key below), the household-size read-back and household-duplicate
256	        // detection alike.
257	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
258	        owner.setHouseholdId(householdId);
259	        // Household-duplicate detection: because the household is keyed on (lastName, postcode), any
260	        // existing owner already carrying this householdId is a member of the same household, so this
261	        // create is a household duplicate. Reject it with 409 unless the caller opts in via
262	        // 'sharesHousehold', which now only bypasses this block (the household link already exists by
263	        // construction) and marks the owner as a declared household member.
264	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
265	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
266	        boolean declaredHouseholdMember = false;
267	        if (householdMemberExists) {
268	            if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
269	                declaredHouseholdMember = true;
270	            } else {
271	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
272	            }
273	        }
274	        // All duplicate detection is consolidated into this single derived identity key
275	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
276	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
277	        // telephone is part of the key, two members of the same household with different telephones
278	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
279	        String identityKey = owner.getIdentityKey();
280	        boolean identityCollision = this.clinicService.findAllOwners().stream()
281	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
282	        if (identityCollision) {
283	            throw new DuplicateIdentityException(identityKey);
284	        }
285	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
286	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
287	        // this owner's last name (compared case-insensitively with collapsed whitespace) and
288	        // postcode while carrying a DIFFERENT normalized telephone. When several existing owners
289	        // match, the one with the lowest id is chosen so the result is deterministic. A declared
290	        // household member is an intentional co-resident, not a suspected duplicate, so it is never
291	        // flagged (a create that reaches this point sharing a last name and postcode with an
292	        // existing owner is precisely a declared household member).
293	        Owner softMatch = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
294	        if (softMatch != null) {
295	            owner.setPossibleDuplicate(true);
296	            owner.setPossibleDuplicateOf(softMatch.getId());
297	        } else {
298	            owner.setPossibleDuplicate(false);
299	        }
300	        // Record how many existing owners already share this first name and last name
301	        // (compared case-insensitively) before this owner is created.
302	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
303	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
304	        owner.setCustomerCode(generateCustomerCode(owner));
305	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
306	        // digits of the registration date year (e.g. 'NSW-1A2B3C4D-M26').
307	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
308	        this.clinicService.saveOwner(owner);
309	        populateHouseholdSize(owner);
310	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
311	        // Emit an audit line carrying the new owner's id, customer code, registration date
312	        // and numeric membership level.
313	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
314	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
315	            ownerDto.getMembershipLevel());
316	        headers.setLocation(UriComponentsBuilder.newInstance()
317	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
318	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
324	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
325	        if (currentOwner == null) {
326	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	        }
328	        currentOwner.setAddress(ownerFieldsDto.getAddress());
329	        currentOwner.setCity(ownerFieldsDto.getCity());
330	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
331	        currentOwner.setLastName(ownerFieldsDto.getLastName());
332	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
333	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
334	        this.clinicService.saveOwner(currentOwner);
335	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
336	    }
337	
338	    /**
339	     * Populate the owner's household size: the number of owners sharing this owner's
340	     * {@code householdId} (including the owner itself). An owner with no household is a household
341	     * of one.
342	     *
343	     * @param owner the owner whose household size should be computed and set
344	     */
345	    private void populateHouseholdSize(Owner owner) {
346	        String householdId = owner.getHouseholdId();
347	        if (!StringUtils.hasText(householdId)) {
348	            owner.setHouseholdSize(1);
349	            return;
350	        }
351	        int size = (int) this.clinicService.findAllOwners().stream()
352	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
353	            .count();
354	        owner.setHouseholdSize(size);
355	    }
356	
357	    /**
358	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
359	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
360	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
361	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
362	     * longer any per-city sequence number.
363	     *
364	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
365	     * @return the generated customer code
366	     */
367	    private String generateCustomerCode(Owner owner) {
368	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
369	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
370	        return region + "-" + hash8;
371	    }
372	
373	    /**
374	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
375	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
376	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
377	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
378	     * known region.
379	     *
380	     * @param postcode the owner's postcode, may be {@code null}
381	     * @param city     the owner's city
382	     * @return the derived region code
383	     */
384	    private String deriveRegion(String postcode, String city) {
385	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
386	            int value = Integer.parseInt(postcode);
387	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
388	                int[] range = entry.getValue();
389	                if (value >= range[0] && value <= range[1]) {
390	                    return entry.getKey();
391	                }
392	            }
393	        }
394	        String region = CITY_REGION.get(city);
395	        return region != null ? region : "UNKNOWN";
396	    }
397	
398	    /**
399	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
400	     * bytes of {@code input}.
401	     *
402	     * @param input  the value to digest
403	     * @param length the number of leading hex characters to return
404	     * @return the truncated upper-case hex digest
405	     */
406	    private String shortSha256Hex(String input, int length) {
407	        try {
408	            byte[] digest = MessageDigest.getInstance("SHA-256")
409	                .digest(input.getBytes(StandardCharsets.UTF_8));
410	            StringBuilder sb = new StringBuilder(digest.length * 2);
411	            for (byte b : digest) {
412	                sb.append(String.format("%02x", b));
413	            }
414	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
415	        } catch (java.security.NoSuchAlgorithmException e) {
416	            throw new IllegalStateException("SHA-256 not available", e);
417	        }
418	    }
419	
420	    /**
421	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
422	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
423	     * that is stored, returned and used for every value derived from it.
424	     *
425	     * @param date the effective registration date (supplied or defaulted)
426	     * @return the same date when it is a weekday, otherwise the next Monday
427	     */
428	    private LocalDate rollToBusinessDay(LocalDate date) {
429	        DayOfWeek dayOfWeek = date.getDayOfWeek();
430	        if (dayOfWeek == DayOfWeek.SATURDAY) {
431	            return date.plusDays(2);
432	        }
433	        if (dayOfWeek == DayOfWeek.SUNDAY) {
434	            return date.plusDays(1);
435	        }
436	        return date;
437	    }
438	
439	    /**
440	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
441	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
442	     *
443	     * @param customerCode     the owner's already-assigned customer code
444	     * @param registrationDate the owner's registration date
445	     * @return the generated membership number
446	     */
447	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
448	        String yy = String.format("%02d", registrationDate.getYear() % 100);
449	        return String.format("%s-M%s", customerCode, yy);
450	    }
451	
452	    /**
453	     * Count the existing owners that share the given first name and last name, comparing each
454	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
455	     * yet persisted, so it is not included in the count.
456	     *
457	     * @param firstName the incoming owner's first name
458	     * @param lastName  the incoming owner's last name
459	     * @return the number of existing namesakes
460	     */
461	    private int countNamesakes(String firstName, String lastName) {
462	        String normalizedFirstName = normalizeForComparison(firstName);
463	        String normalizedLastName = normalizeForComparison(lastName);
464	        return (int) this.clinicService.findAllOwners().stream()
465	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
466	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
467	            .count();
468	    }
469	
470	    /**
471	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
472	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
473	     *
474	     * @param city the incoming owner's city
475	     * @return the number of existing owners already in that city
476	     */
477	    private int countOwnersInCity(String city) {
478	        String normalizedCity = normalizeForComparison(city);
479	        return (int) this.clinicService.findAllOwners().stream()
480	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
481	            .count();
482	    }
483	
484	    /**
485	     * Count the existing owners whose registration date equals the given date. The incoming owner is
486	     * not yet persisted, so it is not included in the count.
487	     *
488	     * @param registrationDate the incoming owner's registration date
489	     * @return the number of existing owners already registered on that date
490	     */
491	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
492	        return (int) this.clinicService.findAllOwners().stream()
493	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
494	            .count();
495	    }
496	
497	    /**
498	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
499	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
500	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
501	     * (postcode is required for the match). When several owners match, the one with the lowest id is
502	     * returned so the result is deterministic; {@code null} when there is no soft match.
503	     *
504	     * @param owner the incoming owner (with normalized telephone and last name resolved)
505	     * @return the lowest-id matching existing owner, or {@code null} when none matches
506	     */
507	    private Owner findPossibleDuplicate(Owner owner) {
508	        if (!StringUtils.hasText(owner.getPostcode())) {
509	            return null;
510	        }
511	        String normalizedLastName = normalizeForComparison(owner.getLastName());
512	        String telephone = owner.getTelephone();
513	        return this.clinicService.findAllOwners().stream()
514	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
515	                && owner.getPostcode().equals(existing.getPostcode())
516	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
517	            .min(java.util.Comparator.comparing(Owner::getId))
518	            .orElse(null);
519	    }
520	
521	    /**
522	     * Generate the deterministic household identifier for the given last name and postcode. The value
523	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
524	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
525	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
526	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
527	     *
528	     * @param lastName the owner's last name
529	     * @param postcode the owner's postcode, may be {@code null}
530	     * @return the deterministic household identifier
531	     */
532	    private String generateHouseholdId(String lastName, String postcode) {
533	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
534	        return shortSha256Hex(key, 12);
535	    }
536	
537	    /**
538	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
539	     * single space, upper-case the result and expand common street-type abbreviations token by token
540	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
541	     * to the empty string. The result is the canonical form that is stored, returned and used for every
542	     * address comparison (household duplicate detection and the shared household id).
543	     *
544	     * @param address the raw address, may be {@code null}
545	     * @return the normalized address
546	     */
547	    private String normalizeAddress(String address) {
548	        if (address == null) {
549	            return "";
550	        }
551	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
552	        if (collapsed.isEmpty()) {
553	            return "";
554	        }
555	        String[] tokens = collapsed.split(" ");
556	        StringBuilder sb = new StringBuilder(collapsed.length());
557	        for (int i = 0; i < tokens.length; i++) {
558	            if (i > 0) {
559	                sb.append(' ');
560	            }
561	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
562	        }
563	        return sb.toString();
564	    }
565	
566	    /**
567	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
568	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
569	     *
570	     * @param value the raw value, may be {@code null}
571	     * @return the normalized value
572	     */
573	    private String normalizeForComparison(String value) {
574	        if (value == null) {
575	            return "";
576	        }
577	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
578	    }
579	
580	    /**
581	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
582	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
583	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
584	     * is returned lower-cased.
585	     *
586	     * @param email the raw email from the request payload, may be {@code null}
587	     * @return the lower-cased email, or {@code null} when none was provided
588	     */
589	    private String normalizeEmail(String email) {
590	        if (!StringUtils.hasText(email)) {
591	            return null;
592	        }
593	        if (!EMAIL_PATTERN.matcher(email).matches()) {
594	            throw new InvalidRequestException(List.of("email"));
595	        }
596	        String lowerCased = email.toLowerCase(Locale.ROOT);
597	        // Reject an address whose domain is on the disposable-domain blocklist.
598	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
599	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
600	            throw new InvalidRequestException(List.of("email"));
601	        }
602	        return lowerCased;
603	    }
604	
605	    /**
606	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
607	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
608	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
609	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
610	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
611	     * to 400 Bad Request).
612	     *
613	     * @param city     the owner's city (used to resolve the region)
614	     * @param postcode the raw postcode from the request payload, may be {@code null}
615	     */
616	    private void validatePostcode(String city, String postcode) {
617	        if (!StringUtils.hasText(postcode)) {
618	            return;
619	        }
620	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
621	            throw new InvalidRequestException(List.of("postcode"));
622	        }
623	        String region = CITY_REGION.get(city);
624	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
625	        if (range != null) {
626	            int value = Integer.parseInt(postcode);
627	            if (value < range[0] || value > range[1]) {
628	                throw new InvalidRequestException(List.of("postcode"));
629	            }
630	        }
631	    }
632	
633	    /**
634	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
635	     * already carries a leading '+' keeps its country code; otherwise the default country code
636	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
637	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
638	     * is thrown (mapped to 400 Bad Request).
639	     *
640	     * @param telephone the raw telephone from the request payload
641	     * @return the E.164 string (e.g. {@code +61412345678})
642	     */
643	    private String normalizeTelephone(String telephone) {
644	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
645	        String candidate;
646	        if (cleaned.startsWith("+")) {
647	            candidate = cleaned;
648	        } else {
649	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
650	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
651	        }
652	        if (!E164_PATTERN.matcher(candidate).matches()) {
653	            throw new InvalidRequestException(List.of("telephone"));
654	        }
655	        // For country codes with a known fixed national-number length, reject a candidate whose
656	        // national digits (everything after the '+' and the country code) do not match that length.
657	        String digits = candidate.substring(1);
658	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
659	            String countryCode = entry.getKey();
660	            if (digits.startsWith(countryCode)) {
661	                int nationalLength = digits.length() - countryCode.length();
662	                if (nationalLength != entry.getValue()) {
663	                    throw new InvalidRequestException(List.of("telephone"));
664	                }
665	                break;
666	            }
667	        }
668	        return candidate;
669	    }
670	
671	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
